export function urlHostMatches(t,e,r={}){if("string"!=typeof t||""===t)return!1;let s;t=t.trim(),!r.allowSchemeless||/^[a-z][a-z0-9+.-]*:/i.test(t)||t.startsWith("/")||t.startsWith("#")||(t="https://"+t);try{s=new URL(t,"https://placeholder.invalid/")}catch{return!1}if("http:"!==s.protocol&&"https:"!==s.protocol)return!1;const o=s.hostname.toLowerCase();return e.some(t=>o===t||o.endsWith("."+t))}